protected static function buildRedirectUrl(string $target, HttpRequest $request, ?string $query): string
{
    $target = trim($target);
    if ($target === '')
        return '';
    //разрешаем полные URL только с хостов текущего сайта
    if (preg_match('#^https?://#i', $target)) {
        $parsed = parse_url($target);
        if ($parsed && isset($parsed['host'])) {
            $allowedHosts = self::getAllowedHosts();
            if (!in_array(strtolower($parsed['host']), $allowedHosts, true)) {
                return ''; //отклоняем сторонний хост
            }
        } else {
            return '';
        }
        return $target;
    }

